import{_ as o,C as s,c as r,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Register a payment","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/payments/register-payment.md","filePath":"master/finance/payments/register-payment.md","lastUpdated":1793074831000}'),l={name:"master/finance/payments/register-payment.md"};function h(c,e,u,m,d,g){const n=s("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="register-a-payment" tabindex="-1">Register a payment <a class="header-anchor" href="#register-a-payment" aria-label="Permalink to &quot;Register a payment&quot;">​</a></h1><p>You register a payment when a customer pays an invoice, or when you pay a vendor bill. You do it from the invoice or bill itself, with the <strong>Pay</strong> button. Aureus creates the payment, posts its journal entry and links it to the document in one step.</p><p>Use this page for full payments, partial payments and payments in another currency.</p><blockquote><p><strong>In simple words:</strong> Open the invoice, click <strong>Pay</strong>, check the amount, click <strong>Pay</strong> again. The invoice shows what is still due.</p></blockquote><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>The invoice or bill must be <strong>Posted</strong>. A draft has no <strong>Pay</strong> button. Click <strong>Confirm</strong> first.</li><li>The <strong>Payment State</strong> must be <strong>Not paid</strong> or <strong>Partial</strong>. A fully paid document hides <strong>Pay</strong>.</li><li>Pay works the same for invoices, credit notes, bills and refunds. This page uses invoice <strong>INV/2026/1</strong> for Azure Interiors. Its total is $1,207.50.</li></ul><p>You find the invoice in either app:</p><ul><li><code>Invoices → Customers → Invoices</code></li><li><code>Accounting → Customers → Invoices</code></li></ul><p>For bills use <code>Invoices → Vendors → Bills</code> or <code>Accounting → Vendors → Bills</code>.</p><h2 id="pay-an-invoice" tabindex="-1">Pay an invoice <a class="header-anchor" href="#pay-an-invoice" aria-label="Permalink to &quot;Pay an invoice&quot;">​</a></h2><ol><li>Open <code>Customers → Invoices</code> and click <strong>INV/2026/1</strong>.</li><li>Click <strong>Pay</strong> in the top bar. The <strong>Pay</strong> window opens.</li></ol>',11)),a(n,{src:"/images1/finance/pay_window_invoice.png",alt:"The Pay window opened from INV/2026/1 with Journal, Payment Method, Amount 1,207.50, Currency USD, Payment Date and Memo filled"}),e[1]||(e[1]=t('<ol start="3"><li>Check each field (see below).</li><li>Click <strong>Pay</strong> at the bottom of the window.</li></ol><p>Aureus closes the window. The invoice page refreshes with the new <strong>Payment State</strong> and <strong>Amount Due</strong>.</p><h3 id="the-fields" tabindex="-1">The fields <a class="header-anchor" href="#the-fields" aria-label="Permalink to &quot;The fields&quot;">​</a></h3><ul><li><strong><em>Journal:</em></strong> The bank or cash journal that receives or sends the money. Pick the journal that matches where the money really goes. The list shows only the journals that fit this document. Aureus picks the first one for you.</li><li><strong><em>Payment Method:</em></strong> How the money moves, for example <strong>Manual Payment</strong>. The options depend on the journal. They are set on each journal under incoming and outgoing payments. See <a href="./../get-started/journals.html">Journals</a>.</li><li><strong><em>Recipient Bank Account:</em></strong> The bank account that gets the money. It shows only on a bill or refund, when the method is <strong>Manual Payment</strong> and the journal is not a cash journal. Pick one of the vendor bank accounts. See <a href="./bank-accounts.html">Bank accounts</a>. On a customer invoice the field is locked.</li><li><strong><em>Amount:</em></strong> How much you pay now. Aureus fills in the amount due. Type a smaller number for a partial payment.</li><li><strong><em>Currency:</em></strong> The currency of the payment. It starts with the journal currency, or the invoice currency if the journal has none. Only active currencies are listed.</li><li><strong><em>Payment Date:</em></strong> The day the money moved. It starts as today. Change it when you register an earlier payment.</li><li><strong><em>Memo:</em></strong> A short note that is saved on the payment. It starts with the invoice number. Add a bank reference here if you have one.</li></ul><h2 id="full-payment-step-by-step" tabindex="-1">Full payment, step by step <a class="header-anchor" href="#full-payment-step-by-step" aria-label="Permalink to &quot;Full payment, step by step&quot;">​</a></h2><p>For <strong>INV/2026/1</strong>, leave the amount at $1,207.50 and click <strong>Pay</strong>. Then check the result:</p><ol><li><strong>Payment State</strong> changes from <strong>Not paid</strong> to <strong>Paid</strong>.</li><li><strong>Amount Due</strong> drops to $0.00.</li><li>The <strong>Pay</strong> button disappears.</li><li>A new payment appears in the <strong>Payments</strong> tab. Its status is <strong>In Process</strong> for a bank journal.</li></ol><p>If you pay with a cash journal, the payment status goes straight to <strong>Paid</strong>.</p>',8)),a(n,{src:"/images1/finance/invoice_after_payment.png",alt:"Paid invoice INV/2026/2 with Payment state Paid, the linked payment PBANK/2026/3 and Amount Due 0.00 in the summary"}),e[2]||(e[2]=t('<h2 id="partial-payment" tabindex="-1">Partial payment <a class="header-anchor" href="#partial-payment" aria-label="Permalink to &quot;Partial payment&quot;">​</a></h2><p>A customer may pay only a part now. Register that part and keep the rest open.</p><ol><li>Open <strong>INV/2026/1</strong> and click <strong>Pay</strong>.</li><li>Change <strong>Amount</strong> to <code>500.00</code>.</li><li>Click <strong>Pay</strong>.</li></ol><p>The result:</p><ul><li><strong>Payment State</strong> is <strong>Partial</strong>.</li><li><strong>Amount Due</strong> is $707.50.</li><li>The <strong>Pay</strong> button stays. Use it again for the rest.</li></ul><p>Click <strong>Pay</strong> a second time. The window now offers $707.50. Confirm it and the invoice becomes <strong>Paid</strong>.</p><h2 id="installments-and-the-full-amount" tabindex="-1">Installments and the full amount <a class="header-anchor" href="#installments-and-the-full-amount" aria-label="Permalink to &quot;Installments and the full amount&quot;">​</a></h2><p>Some payment terms split an invoice into several due dates. See <a href="./../customer-invoices/payment-terms.html">Payment terms</a>. In that case the <strong>Amount</strong> field may start with only the part that is due first.</p><p>A small link sits above the <strong>Amount</strong> field. It reads <strong>installments</strong> or <strong>full amount</strong>.</p><ul><li>Click <strong>full amount</strong> to pay the whole open balance.</li><li>Click <strong>installments</strong> to go back to the next installment.</li></ul><p>Under the field a hint says which one you see, for example &quot;This is the full amount.&quot;</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>An invoice with a single due date has only one amount. The link and the hint then do not appear.</p></div><h2 id="pay-in-another-currency" tabindex="-1">Pay in another currency <a class="header-anchor" href="#pay-in-another-currency" aria-label="Permalink to &quot;Pay in another currency&quot;">​</a></h2><p>You can pay in a currency that differs from the invoice.</p><ol><li>Open the <strong>Pay</strong> window.</li><li>Change <strong>Currency</strong> to the currency the customer used.</li><li>Check the <strong>Amount</strong>. It stays in the number you type.</li><li>Set the <strong>Payment Date</strong>. Aureus uses the rate of that date to convert.</li></ol><p>The invoice is settled in its own currency. If the rate on the payment date differs from the invoice date, Aureus may book an exchange difference. The gain and loss accounts come from the default accounts. See <a href="./../get-started/default-accounts.html">Default accounts</a> and <a href="./../get-started/multi-currency.html">Multi-currency</a>.</p><h2 id="the-summary-box-on-the-invoice" tabindex="-1">The summary box on the invoice <a class="header-anchor" href="#the-summary-box-on-the-invoice" aria-label="Permalink to &quot;The summary box on the invoice&quot;">​</a></h2><p>The box at the bottom right of an invoice lists the payments tied to it.</p><ul><li><strong>Paid payments:</strong> Each paid line shows the payment, the date and the amount. Click <strong>Unlink</strong> to break the link. The amount goes back to <strong>Amount Due</strong>. Aureus asks you to confirm.</li><li><strong>Outstanding credits</strong> (or <strong>Outstanding debits</strong> on a bill): Money from this partner that is posted but not yet matched, for example an advance. Click <strong>Add</strong> to apply it to this document. Aureus asks you to confirm.</li></ul>',19)),a(n,{src:"/images1/finance/invoice_summary_reconcile.png",alt:"Invoice summary of INV/2026/2 with the totals, the linked payment PBANK/2026/3 with the Unlink button and Amount Due 0.00"}),e[3]||(e[3]=t('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Unlink</strong> does not delete the payment. It only removes the link. The payment stays in the list.</p></div><h2 id="pay-a-vendor-bill" tabindex="-1">Pay a vendor bill <a class="header-anchor" href="#pay-a-vendor-bill" aria-label="Permalink to &quot;Pay a vendor bill&quot;">​</a></h2><p>The steps are the same. Open <code>Vendors → Bills</code>, open a posted bill and click <strong>Pay</strong>. The payment has the type <strong>Send</strong>. The <strong>Recipient Bank Account</strong> is where your money goes.</p><h2 id="what-if-something-fails" tabindex="-1">What if something fails <a class="header-anchor" href="#what-if-something-fails" aria-label="Permalink to &quot;What if something fails&quot;">​</a></h2><p>If Aureus cannot create the payment, a <strong>Payment Failed</strong> message appears with the reason. Nothing is saved. Fix the cause and try again.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./manage-payments.html">Manage payments</a></li><li><a href="./">Payments overview</a></li><li><a href="./../customer-invoices/create-invoice.html">Create an invoice</a></li><li><a href="./../vendor-bills/create-bill.html">Create a bill</a></li><li><a href="./../accounting-entries/journal-entries.html">Journal entries</a></li></ul>',7))])}const f=o(l,[["render",h]]);export{y as __pageData,f as default};
